import { App, Button, useMessage } from 'vellum-ui'

function SaveButton() {
  const message = useMessage()
  return (
    <Button variant="primary" onClick={() => message.success('Saved')}>
      Save
    </Button>
  )
}

export function Basic() {
  return (
    <App>
      <SaveButton />
    </App>
  )
}
